raw=P/'raw/whole-pickup-attempt2.png';im=Image.open(raw).convert('RGBA');canvas=[(im.width+3)//4,(im.height+3)//4];frames=[];proof=[]
# Manually traced face-bottom guides in source grid coordinates, provisional.
chins=[146,169,184,188,193,195,207,221,155,139,142,134,122,125,126,123]
for i in range(16):
 col=i%4;row=i//4;r=[col*im.width//4,row*im.height//4,(col+1)*im.width//4,(row+1)*im.height//4];full=Image.new('RGBA',canvas);full.paste(im.crop(r),(0,0));y=chins[i];polygon=[[70,0],[212,0],[212,y-35],[178,y-10],[156,y+2],[126,y+2],[104,y-10],[70,y-35]];mask=Image.new('L',canvas);ImageDraw.Draw(mask).polygon([tuple(x)for x in polygon],fill=255);empty=Image.new('RGBA',canvas);head=Image.composite(full,empty,mask);body=Image.composite(empty,full,mask);composite=Image.alpha_composite(body,head)
 import numpy as np
 a=np.array(full);b=np.array(composite);visible=a[:,:,3]>0;assert np.array_equal(a[:,:,3],b[:,:,3])and np.array_equal(a[visible],b[visible])
 slots={}
