assetpaths={s['asset']for f in frames for s in f['slots'].values()if s};assets={n:'data:image/png;base64,'+base64.b64encode((P/n).read_bytes()).decode()for n in assetpaths};js=(P/'four-slot-player.js').read_text().replace('export ','')
html='''<!doctype html><meta charset="utf-8"><title>Whole body + head · rejected motion study</title><style>body{background:#20242a;color:#eee;font:16px system-ui;margin:24px}canvas{background:#353a42;border:1px solid #777;width:420px;max-width:90vw;image-rendering:auto}button,input,select{margin:8px}aside{max-width:800px}</style><h1>ตัวเต็ม + หัวพร้อมผม</h1><aside>ต้นแบบโครงสร้าง · ภาพท่าก้มยังไม่ผ่านจังหวะและตำแหน่งเท้า ห้ามนำผลตรวจการประกอบเลเยอร์มาอ้างว่าภาพท่าทางผ่านแล้ว</aside><p><button id="play">เล่น/หยุด</button><select id="rate"><option value="1">1×</option><option value="0.25">¼×</option></select><input id="seek" type="range" min="0" max="15" value="0"><span id="label"></span></p><p><label><input type="checkbox" id="body" checked>ตัวทั้งชิ้น</label><label><input type="checkbox" id="head" checked>หัวและผม</label></p><canvas id="c"></canvas><script>'''+js+'\nconst clip='+json.dumps(clip)+';const assets='+json.dumps(assets)+''';const images=new Map();const canvas=document.querySelector('#c');canvas.width=clip.canvas[0];canvas.height=clip.canvas[1];const ctx=canvas.getContext('2d');let playing=false,time=0,last=0,index=0;const seek=document.querySelector('#seek');const body=document.querySelector('#body'),head=document.querySelector('#head');function draw(i){index=i;const f=clip.frames[i];ctx.clearRect(0,0,...clip.canvas);for(const n of f.order){if(n==='body'&&!body.checked||n==='head'&&!head.checked)continue;const s=f.slots[n];if(s)ctx.drawImage(images.get(s.asset),0,0);}seek.value=i;document.querySelector('#label').textContent=(i+1)+'/16';}function select(i){playing=false;time=clip.frames.slice(0,i).reduce((n,f)=>n+f.duration_ms,0);draw(i);}seek.oninput=()=>select(+seek.value);body.onchange=head.onchange=()=>draw(index);document.querySelector('#play').onclick=()=>{playing=!playing;last=performance.now();};function tick(now){if(playing){time+=(now-last)*+document.querySelector('#rate').value;draw(frameAt(clip,time));}last=now;requestAnimationFrame(tick);}window.prototypeStudy={clip,images,select,draw,ctx,frameAt,validateClip,drawFrame};Promise.all(Object.entries(assets).map(([n,url])=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images.set(n,im);resolve();};im.onerror=reject;im.src=url;}))).then(()=>{validateClip(clip);draw(0);window.READY=true;requestAnimationFrame(tick);}).catch(e=>{window.LOAD_ERROR=String(e);});</script>'''
